package com.example.pc02moviles2320047322200234

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import com.example.pc02moviles2320047322200234.ui.HomeScreen
import com.example.pc02moviles2320047322200234.ui.RegistroEquipoScreen
import com.example.pc02moviles2320047322200234.ui.theme.PC02MOVILES2320047322200234Theme

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            PC02MOVILES2320047322200234Theme {
                // A surface container using the 'background' color from the theme
                Surface(modifier = Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
                    val currentScreen = remember { mutableStateOf("home") }

                    when (currentScreen.value) {
                        "home" -> HomeScreen(onNavigateToRegistro = { currentScreen.value = "registro_equipo" })
                        "registro_equipo" -> RegistroEquipoScreen()
                    }
                }
            }
        }
    }
}

package com.example.pc02moviles2320047322200234.presentation.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.pc02moviles2320047322200234.data.Equipo
import com.google.firebase.firestore.ktx.firestore
import com.google.firebase.ktx.Firebase

class EquipoViewModel : ViewModel() {
    var nombre by mutableStateOf("")
    var anioFundacion by mutableStateOf("")
    var titulosGanados by mutableStateOf("")
    var imagenUrl by mutableStateOf("")

    fun addEquipo() {
        val anioFundacionInt = anioFundacion.toIntOrNull() ?: 0
        val titulosGanadosInt = titulosGanados.toIntOrNull() ?: 0

        val equipo = Equipo(
            nombre = nombre,
            anio_fundacion = anioFundacionInt,
            titulos_ganados = titulosGanadosInt,
            imagen_url = imagenUrl
        )
        Firebase.firestore.collection("equipos").add(equipo)
        nombre = ""
        anioFundacion = ""
        titulosGanados = ""
        imagenUrl = ""
    }
}

package com.example.pc02moviles2320047322200234.presentation.viewmodel

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import com.example.pc02moviles2320047322200234.data.Equipo
import com.google.firebase.firestore.ktx.firestore
import com.google.firebase.ktx.Firebase

class EquipoViewModel : ViewModel() {
    var nombre by mutableStateOf("")
    var anioFundacion by mutableStateOf("")
    var titulosGanados by mutableStateOf("")
    var imagenUrl by mutableStateOf("")

    // Estado para comunicar resultado (éxito/error) a la UI
    var statusMessage by mutableStateOf("")

    fun addEquipo() {
        // Validación mínima
        if (nombre.isBlank()) {
            statusMessage = "El nombre del equipo es obligatorio"
            return
        }

        val anioFundacionInt = anioFundacion.toIntOrNull() ?: 0
        val titulosGanadosInt = titulosGanados.toIntOrNull() ?: 0

        val equipo = Equipo(
            nombre = nombre,
            anio_fundacion = anioFundacionInt,
            titulos_ganados = titulosGanadosInt,
            imagen_url = imagenUrl
        )

        Firebase.firestore.collection("equipos")
            .add(equipo)
            .addOnSuccessListener {
                statusMessage = "Equipo registrado correctamente"
                // limpiar campos
                nombre = ""
                anioFundacion = ""
                titulosGanados = ""
                imagenUrl = ""
            }
            .addOnFailureListener { e ->
                statusMessage = "Error al registrar: ${e.message}"
            }
    }

    fun clearStatus() {
        statusMessage = ""
    }
}

